        case kWrType: if (lf || rt || act) { g_WpType = (g_WpType + (lf ? wpdata::kTN - 1 : 1)) % wpdata::kTN; g_WpSel = 0; g_WxDirty = true; } break;
        case kWrSel: if (lf || rt || act) { const int n = wpdata::kTypeFirst[g_WpType + 1] - wpdata::kTypeFirst[g_WpType]; g_WpSel = (g_WpSel + (lf ? n - 1 : 1)) % n; g_WxDirty = true; } break;
        case kWrMain: if (act || rt) { g_WxPG = -1; g_SelPanel = 13; g_SelCur = 0; g_SelScroll = 0; g_WxDirty = true; } break;
        case kWrGrp: if (act || rt) { g_WxPG = r.a; g_SelPanel = 13; g_SelCur = 0; g_SelScroll = 0; g_WxDirty = true; } break;
        case kWrKnob: case kWrParam: { int* d = WxDelta(j); if (!d) break; if (act) { if (*d != 0) { *d = 0; WxTouch(); } } else if (lf) WxAdd(j, -1); else if (rt) WxAdd(j, 1); break; }
        case kWrRst: if (act) { const int w = WpCur(); for (int k = 0; k < 5; k++) g_WxKd[w][k] = 0; for (int p = wxd::kWPF[w]; p < wxd::kWPF[w + 1]; p++) g_WxPd[p] = 0; WxTouch(); g_WpRstT = NowTick(); } break;
        case kWrRstAll: if (act) { for (int w = 0; w < wpdata::kWN; w++) for (int k = 0; k < 5; k++) g_WxKd[w][k] = 0; for (int p = 0; p < wxd::kPN; p++) g_WxPd[p] = 0; WxTouch(); g_WpRstAllT = NowTick(); } break;
