    /* 左右の長押し: 0.3 秒たったら 0.025 秒ごとに続けて変える。長く押すほど、1 回に動く量が増える (遅くならない)。値が大きいときは、値に比例して動く */
    void WxHold(u64 nw, int j, bool left, bool edgeNow) {
        static u64 st = 0, lastRep = 0;
        if (edgeNow || st == 0) { st = nw; lastRep = nw + 5760000ull - 480000ull; return; }
        const u64 held = nw - st; if (held < 5760000ull) return;
        const int* d = WxDelta(j); if (!d) return;
        const float hs = static_cast<float>(held) / 19200000.0f;
        int n = 0; while (nw - lastRep >= 480000ull && n < 6) {
            lastRep += 480000ull; n++; if (nw < g_WxPauseT) continue;
            const int cur = *d, ab = cur < 0 ? -cur : cur; int base = hs < 0.6f ? 1 : (hs < 1.0f ? 3 : (hs < 1.6f ? 6 : (hs < 2.4f ? 12 : (hs < 3.5f ? 25 : 50))));
            const float fr = hs < 1.0f ? 0.0f : (hs < 2.0f ? 0.015f : (hs < 3.5f ? 0.03f : 0.07f));
            int amt = (base + static_cast<int>(static_cast<float>(ab) * fr)) * 5; WxAdd(j, left ? -amt : amt);
        }
        if (nw - lastRep > 4800000ull) lastRep = nw;
    }
    void WxHoldEnd() { WxHold(0, 0, false, true); }
