        const uintptr_t aTc = GotAt(0x4E98980), aWork = GotAt(0x4E98990), aStr = GotAt(0x4E989A0), aPre = GotAt(0x4E989C0), aIni = GotAt(0x4E989D0), aShow = GotAt(0x4E989E0);
