        if (g_SymN > 0) { int L = 0; while (ini[L] && L < 99) L++; SymPendU8(ini + L, 100 - L); } /* tmt: 選んだ記号を入力欄の後ろに */
        *reinterpret_cast<u32*>(g_KbArg + 0x3b8) = 1; g_KbArg[0x3bc] = 1; /* tmt: 改行も使える */
