        if (b->rest < 0) { const float qx = P[0] - b->rp[0], qy = P[1] - b->rp[1], qz = P[2] - b->rp[2]; if (qx * qx + qy * qy + qz * qz > 9.0f) { b->rest = 0; b->rt = 0; } else if (++b->rt > 120) { b->rest = 0; b->rt = 0; b->stuck = 0; /* 版 692: 2 秒たっても箱から出てこない (ふつうの bot は自分では動かない) ときは、こちらから動かして出す。前は永久に止まったままだった */ } else { b->last[0] = P[0]; b->last[1] = P[1]; b->last[2] = P[2]; b->have = true; return; } } /* 復活の箱の中: 自分で出てくるまで触らない */
        if (b->rest > 0) { b->rest--; b->last[0] = P[0]; b->last[1] = P[1]; b->last[2] = P[2]; b->have = true; return; } /* 版 658: 復活の直後などはゲームに任せる (箱から出られない対策) */
        if (b->have) { const float jx = P[0] - b->last[0], jy2 = P[1] - b->last[1], jz = P[2] - b->last[2];
            if (jx * jx + jy2 * jy2 + jz * jz > 4.0f * 4.0f * (1.0f + 4.0f * g_CcDt * g_CcDt * 100.0f) && jx * jx + jy2 * jy2 + jz * jz > 36.0f) { b->rest = -1; b->rt = 0; b->rp[0] = P[0]; b->rp[1] = P[1]; b->rp[2] = P[2]; b->air = 0; b->vv = 0; b->stuck = 0; b->last[0] = P[0]; b->last[1] = P[1]; b->last[2] = P[2]; return; } } /* 位置が急に飛んだ = 復活・ワープ */
        float vy;
