    /* 版 679: 最強チート = 任天堂のサーバーへの接続を遮断する (90DNS と同じ: 名前を引くと失敗する)。
       名前を引く関数 (nn::socket の GetAddrInfo / GetHostByName) に割り込み、名前に "nintendo" を含むときだけ失敗を返す。それ以外 (アップデート用の GitHub など) は通す */
    static bool NinHost(const char* h) {
        if (!h) return false;
        for (const char* p = h; *p; p++) {
            if ((p[0] | 32) == 'n' && (p[1] | 32) == 'i' && (p[2] | 32) == 'n' && (p[3] | 32) == 't' && (p[4] | 32) == 'e' && (p[5] | 32) == 'n' && (p[6] | 32) == 'd' && (p[7] | 32) == 'o') return true;
        }
        return false;
    }
    HOOK_DEFINE_TRAMPOLINE(DnsGaiHook) {
        static int Callback(const char* node, const char* svc, const void* hints, void** res) {
            if (g_NetBlk && NinHost(node)) { if (res) *res = nullptr; return 8; } /* 8 = 名前が見つからない */
            return Orig(node, svc, hints, res);
        }
    };
    HOOK_DEFINE_TRAMPOLINE(DnsGhbnHook) {
        static void* Callback(const char* name) {
            if (g_NetBlk && NinHost(name)) return nullptr;
            return Orig(name);
        }
    };
