        MemoryInfo selfmi; u32 selfpg; uintptr_t selfLo = 0, selfHi = 0; if (R_SUCCEEDED(svcQueryMemory(&selfmi, &selfpg, reinterpret_cast<uintptr_t>(g_EbBuf)))) { selfLo = selfmi.addr; selfHi = selfmi.addr + selfmi.size; }
